ProjectALife.DialogueShards["scenes_any_27"] = {
{"s6_gear_one_at_a_time_019","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"One rifle broken down at a time - never two",2,"I know it",1,"Knowing it and doing it were two different people last night"}},
{"s6_gear_extractor_spring_020","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"If an extractor spring failed, would you try using that weapon anyway?",2,"Not without the right spare",1,"I'd rather admit it was out of action",2,"Even if you needed it later?",1,"Especially then. Needing it doesn't fix it"}},
{"s6_gear_dump_plates_021","any",2,"reg=elite|tmp=veteran|day=2,999|mood=calm",{1,"Dump the plates, too hot, and nothing out here bites through a vest anyway",2,"Raiders shoot",1,"Raiders shoot like they drive - keep the vest, dump the plates"}},
{"s6_gear_break_glass_022","any",2,"reg=elite|tmp=veteran|mood=funny|world=door",{1,"Where'd the axe come from?",2,"Fire station in Rosewood, glass case by the bay door",1,"Break glass in case of emergency",2,"Seemed to qualify"}},
{"s6_gear_speckled_tube_023","any",2,"reg=elite|tmp=veteran|hour=20,5|mood=calm",{1,"Tube on my goggles is going, the green's all speckled",2,"Still better than the moon",1,"The moon isn't running out of batteries"}},
{"s6_gear_team_total_024","any",2,"reg=elite|tmp=veteran|day=20,999|mood=grim",{1,"Team total, rifle ammunition?",2,"{count} rounds",1,"Say again",2,"You heard it right the first time"}},
{"s6_gear_police_brass_025","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Police your brass",2,"Nobody's tracking brass out here",1,"Somebody who reloads is, and anybody who picks it up knows what we carry"}},
{"s6_gear_five_fifty_026","any",1,"reg=elite|tmp=veteran|day=15,999|mood=funny",{1,"Tape, cord, tape, cord",1,"Whole rifle's held together with five-fifty and good intentions",1,"Mostly five-fifty"}},
{"s6_gear_brochure_skulls_027","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=funny",{1,"Blade's dull again",2,"Skulls do that",1,"Nobody mentioned skulls in the brochure"}},
{"s6_gear_lanyard_028","any",2,"reg=elite|tmp=veteran|mood=calm|world=vehicle,window",{1,"Lanyard the pistol",2,"Feels like basic",1,"Basic didn't have a hand coming through a car window for your holster"}},
{"s6_gear_wall_rifles_029","any",3,"reg=elite|tmp=veteran|mood=funny|world=building",{1,"Gun shop on {street} is picked clean",2,"Locals?",3,"Locals, took the rifles off the wall and left every box of ammunition",1,"So there's a man out there with a mounted deer rifle and nothing to put in it",2,"Best kind of armed"}},
{"s6_gear_surplus_patches_030","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Surplus store in Muldraugh had cleaning kits",2,"Issue?",1,"Issue - Vietnam era, the patches are older than you",2,"Still cleaner than my rifle"}},
{"s6_gear_jam_review_031","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"You name your rifle?",2,"No",1,"You call it something every time it jams",2,"A name, no, sounds more like a review"}},
{"s6_gear_pin_backwards_032","any",2,"reg=elite|tmp=veteran|day=5,999|mood=grim",{1,"You put that pin in backwards twice",2,"Didn't sleep",1,"I'll do it",2,"I can do my own rifle",1,"Then do it right the third time"}},
{"s6_gear_muzzles_under_033","any",2,"reg=elite|tmp=veteran|mood=calm|world=water",{1,"Waded the creek east of Echo Creek, muzzles went under",2,"Clear the bores before anybody fires",1,"Doing it",2,"Do it before you tell me you're doing it"}},
{"s6_gear_machete_stuck_034","any",3,"reg=elite|tmp=veteran|mood=funny|world=door",{1,"Crowbar or machete?",2,"Crowbar, opens a door, opens a head",3,"Machete stuck in one for ten minutes at the post office - had to put my boot on its chest",1,"Crowbar"}},
{"s6_gear_breast_pocket_035","any",2,"reg=elite|tmp=veteran|day=3,999|mood=grim",{1,"Keep one round apart from the rest",2,"In the pistol?",1,"Left breast pocket, you'll know what it's for",2,"Mine's been in there since the second night"}},
{"s6_gear_three_round_bursts_036","any",2,"reg=elite|tmp=veteran|day=8,999|mood=calm",{1,"SAW goes to short bursts - three rounds",2,"Three rounds won't stop a crowd",1,"Nothing stops a crowd, three rounds buys the time to leave"}},
{"s6_gear_wipe_the_face_037","any",1,"reg=elite|tmp=veteran|hour=20,2|mood=grim",{1,"Oil the bolt, oil the rails - wipe the face",1,"Man in Riverside had a face like that - clean-shaven, still had his tie on",1,"Wipe the face"}},
{"s6_gear_oil_filter_038","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"You are not putting an oil filter on the end of that rifle",2,"Saw it done in El Salvador",1,"Did it work in El Salvador?",2,"Once"}},
{"s6_gear_quiet_miss_039","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Sporting goods in Brandenburg had a compound bow",2,"Can you shoot a bow?",1,"Not well",2,"Then it's a very quiet way to miss"}},
{"s6_gear_ten_feet_040","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Arm's length is too close",2,"Rifle's length?",1,"Rifle's length is too close, anything under ten feet is a mistake somebody made"}},
{"s6_gear_sixty_pounds_041","any",3,"reg=elite|tmp=veteran|day=0,12|mood=calm",{1,"Redistribute, nobody over sixty pounds",2,"The radio's twenty by itself",3,"I'll take the radio",1,"You carried it yesterday - give it here"}},
{"s6_gear_taped_lens_042","any",2,"reg=elite|tmp=veteran|hour=19,5|mood=calm",{1,"Tape the lens - leave a slit",2,"Can't see a thing through a slit",1,"Neither can the man on the ridge with the deer rifle"}},
{"s6_gear_his_tape_043","any",2,"reg=elite|tmp=veteran|day=4,999|mood=sad",{1,"That's Kowalski's rifle",2,"It's the team's rifle",1,"It's got his tape on the stock",2,"Then it's got his tape on the stock - clean it"}},
{"s6_gear_left_a_five_044","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"Hardware store in West Point, sewing machine oil, two cases",2,"That'll do",1,"Lady behind the counter would've charged sixty cents a bottle",2,"Leave a dollar",1,"Left a five"}},
{"s6_gear_stairwell_ears_045","any",2,"reg=elite|tmp=veteran|mood=funny|world=stairs",{1,"What?",2,"I said you should've had plugs in for the stairwell",1,"What?",2,"Never mind"}},
{"s6_gear_double_feed_porch_046","any",3,"reg=elite|tmp=veteran|mood=calm|world=building",{1,"Double feed, right on the porch",2,"What'd you do?",1,"Went to pistol",3,"And?",1,"And I'm sitting here cleaning a rifle, aren't I?"}},
{"s6_gear_post_office_mags_047","any",2,"reg=elite|tmp=veteran|hour=4,8|mood=calm",{1,"Stand-to - kit check",2,"Rifle, pistol, knife, water, two mags light",1,"Why light?",2,"Because the post office happened"}},
{"s6_gear_toy_aisle_048","any",1,"reg=elite|tmp=veteran|day=10,999|mood=funny|world=vehicle",{1,"Government night vision, several thousand dollars, give or take",1,"Running on batteries out of a kid's remote-control truck",1,"Kid won't mind"}},
{"s7_c01_clothesline_diapers_001","any",3,"reg=raider|tmp=predator|day=3,200|mood=grim|world=door",{1,"Yellow house on {street}, cloth diapers on the clothesline, washed yesterday",2,"So there's a baby",1,"And a mama still doing laundry, that's a house that opens the door quiet",3,"Or a daddy behind the door with a deer rifle, 'cause there's a baby",1,"Then we wait for him to go out for water - everybody goes out for water"}},
{"s7_c01_chalk_driveway_002","any",2,"reg=raider|tmp=predator|day=3,200|mood=calm|world=building,rain",{1,"Chalk on the driveway at the brick ranch - Hopscotch, the rain Tuesday would've washed that off",2,"So it's fresh",1,"So somebody's still letting a kid play outside, that's brave or it's stupid",2,"Either way they got food, you don't let a hungry kid hop"}},
{"s7_c01_family_census_003","any",3,"reg=raider|tmp=predator|day=5,200|mood=funny",{1,"How many houses in {town} still got families in 'em? Real number",2,"Five - Doublewide past the Baptist church, two on the hill, the green one, the one with the ham antenna",3,"Six, you forgot the old couple with the goats",2,"Two people and some goats, that's a family now?",3,"They're a family to the goats",1,"Five and the goats - write it down"}},
{"s7_c01_candle_hip_high_004","any",2,"reg=raider|tmp=predator,seasoned|hour=21,4|mood=sad|world=window,building",{1,"Upstairs window on the corner house - candle",2,"Moving, too, somebody's walking a kid to the bathroom",1,"How do you know it's a kid?",2,"Candle's down at hip height, my mama made that same walk with me",1,"Don't tell me stuff like that when we're working"}},
{"s7_c01_scrubs_keys_005","any",3,"reg=raider|tmp=predator|mood=grim",{1,"The lady in scrubs kept her car keys balled up in her fist the whole time",2,"Like she was gonna stab somebody with a Honda key",1,"She kept saying she had a shift at seven, there ain't no shift at seven",3,"Hospital's still running in her head, I guess",2,"Well, she's walking to work now"}},
{"s7_c01_hearse_coffee_006","any",2,"reg=raider|tmp=predator|mood=funny|world=road",{1,"Stopped a hearse on the Ekron road, driver swore up and down he was on a call",2,"What was in the back?",1,"A casket, I made him open it",2,"And?",1,"Forty pounds of ground coffee and a pump shotgun, smartest undertaker in Kentucky"}},
{"s7_c01_bmx_backpacks_007","any",3,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Two boys on BMX bikes - fifteen, maybe, backpacks full of Pop-Tarts",2,"You took the bikes?",1,"Took the backpacks, left the bikes",3,"Boss wanted bikes, boss said bikes, specifically",1,"They were fifteen - tell him I missed 'em, if you want to tell him something",3,"I ain't telling him nothing"}},
{"s7_c01_mailbox_names_008","any",2,"reg=raider|tmp=predator|day=3,200|mood=calm",{1,"Mailboxes on {street} still got the names - Hollins, Sapp, Mercer, Dobbs",2,"Mercer, that's the one with the bass boat in the drive",1,"Boat means gas cans close by, nobody keeps a boat without gas",2,"Mercer also means three boys that played football, I went to school with their daddy",1,"Then we go when the boys go hunting"}},
{"s7_c01_paper_towel_rig_009","any",2,"reg=raider|mood=funny",{1,"Trucker parked at the weigh station, whole trailer of paper towels",2,"The whole trailer?",1,"Forty-eight feet of paper towels, he'd been living on the CB and gas station jerky",2,"Grab a case, we been wiping with phone book pages",1,"Took ten cases, he asked to keep his CB, I let him keep his CB"}},
{"s7_c01_cake_topper_010","any",3,"reg=raider|tmp=predator,seasoned|day=1,40|mood=sad",{1,"That couple in the Cutlass had rice all down in the floor mats",2,"Just married",1,"Cake topper in the glovebox, little plastic bride and groom, frosting still on their feet",3,"What'd they actually have?",1,"Two hundred cash out of the card envelopes, cards all said congratulations"}},
{"s7_c01_garden_hose_011","any",2,"reg=raider|mood=funny",{1,"Old boy on the Dixie Highway came at us with a garden hose",2,"Was the water on?",1,"No, that's what gets me - he just held the nozzle up like a pistol",2,"What'd you do?",1,"Put my hands up, it seemed fair"}},
{"s7_c01_look_at_the_kid_012","any",2,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"Houses with kids go easy, you point at the kid, the daddy opens the gun safe",2,"I ain't pointing at no kid",1,"You don't have to point, you just have to look at the kid a certain way",2,"I ain't looking, either",1,"Then go stand in the yard and look at the dog - useless"}},
{"s7_c01_new_net_013","any",3,"reg=raider|tmp=predator|day=4,200|mood=grim|world=stairs",{1,"Brick ranch with the basketball goal - Net's brand new, somebody hung it this week",2,"Who hangs a basketball net right now?",1,"A daddy trying to make it feel like summer vacation",3,"A daddy with a ladder and time on his hands - so he's got a garage full of stuff",1,"Or a daddy who'd die before he let you in that garage"}},
{"s7_c01_july_chimney_014","any",2,"reg=raider|tmp=predator|hour=5,10|mood=calm|world=summer",{1,"Smoke out of a chimney in summer, north end of {town}",2,"Cooking on a woodstove, the electric range is dead",1,"Means they got wood, food, and they ain't scared to be seen",2,"Means they got a reason not to be scared - count the guns before you count the cans"}},
{"s7_c01_already_robbed_sign_015","any",2,"reg=raider|tmp=predator|mood=funny|world=door",{1,"Garage door said ROBBED ALREADY, NOTHING LEFT - and underneath it, 'God bless'",2,"Was it true?",1,"Two hams in the chest freezer under a sack of kitty litter",2,"God bless, then"}},
{"s7_c01_mutter_house_list_016","any",1,"reg=raider|tmp=predator|day=3,200|mood=grim|world=water,road",{1,"Green house, two men, one limps - Doublewide, a woman and three kids, no gun seen",1,"Farmhouse off the creek road, dogs, too many dogs - skip the farmhouse",1,"Doublewide first - Doublewide Thursday"}},
{"s7_c01_band_candy_017","any",3,"reg=raider|mood=funny|world=vehicle",{1,"Woman had a whole case of the school fundraiser chocolate bars - one dollar, says right on the wrapper",2,"Melted?",1,"Melted and set back up about three times, they're all one shape now",3,"Label says band trip to Nashville",2,"Band ain't going to Nashville",3,"Some kid was gonna ride a bus to Nashville on these"}},
{"s7_c01_insurance_man_018","any",2,"reg=raider|tmp=predator|mood=funny",{1,"Fella tried to hand me his business card, said call him when this is over, he'll make it worth our while",2,"What's he do?",1,"Sells insurance out of a little office in Brandenburg",2,"Ask him does he cover this",1,"I did, he said he'd have to look at the policy"}},
{"s7_c01_barking_short_list_019","any",3,"reg=raider|tmp=predator|day=5,200|mood=grim|world=road",{1,"Every house on {street} that's still got a family has a dog that barks at night",2,"And every dog that barks pulls the dead down the street",1,"So them families ain't gonna be there long anyhow",3,"So we hit 'em first, before the dead do it for free?",1,"I didn't say that, I said it's a short list"}},
{"s7_c01_get_out_slow_020","any",3,"reg=raider|tmp=predator,seasoned|mood=sad|world=vehicle",{1,"Woman in the Grand Am was pregnant, way along, too",2,"We still took the car",3,"We took the car and she walked, in this heat",2,"She had a husband, he can carry her",3,"He was the one talking her out of the seat - real gentle - get out slow, Tammy - slow",2,"Don't say her name - why'd you even keep her name?"}},
{"s7_c01_blue_chalk_021","any",3,"reg=raider|tmp=predator|day=6,200|mood=fear|world=road",{1,"Somebody's marking doors on {street} - blue chalk, little X by the knob",2,"That ain't us",1,"I know it ain't us, we use orange paint - so who's using blue?",3,"Brandenburg crew, or the Army, counting",1,"Either one, somebody's working our street"}},
{"s7_c01_grand_canyon_022","any",2,"reg=raider|mood=funny|world=water",{1,"Retired couple in a motor home down at the lake - Florida plates",2,"Florida? What are they doing in Kentucky at all?",1,"Said they were on their way to the Grand Canyon",2,"This is a long way wrong for the Grand Canyon",1,"He wouldn't stop and ask directions, she told us that part twice while we loaded her groceries"}},
{"s7_c01_seven_fifteen_023","any",2,"reg=raider|tmp=predator|day=4,200|mood=calm|world=vehicle,water",{1,"Garage on 31W, family living in the office, man, wife, grown son",2,"Son's the problem, son carries a tire iron and don't set it down",1,"Son walks to the creek with jugs every morning - seven, seven-thirty",2,"Then it's seven-fifteen",1,"Seven-fifteen, and nobody touches the mama",2,"Nobody said nothing about the mama",1,"I'm saying it"}},
{"s7_c01_polaroid_faces_024","any",3,"reg=raider|tmp=predator|mood=fear",{1,"Why are you taking their picture?",2,"Camera was in their van, figured they'd want something to remember us by",1,"Put it away, a picture of your face is how people find you",2,"Find me where? Who's looking? The post office?",3,"The Army, the Army looks at pictures"}},
{"s7_c01_gaines_mother_025","any",3,"reg=raider|tmp=predator,seasoned|day=7,60|mood=sad",{1,"Woman at the gas station in Irvington looked right at Ricky - said, Ricky Gaines, I know your mother",2,"What'd Ricky do?",3,"Pulled my bandana down, said yes ma'am, said tell her I'm eating good",1,"Then we took her gas",3,"She said my mother'd be ashamed, mama's been gone a week Sunday - I didn't tell her that"}},
{"s7_c01_neighbor_names_026","any",2,"reg=raider|tmp=predator|day=4,200|mood=grim|world=generator",{1,"Lady on {street} didn't have nothing, so she paid us in names",2,"Names?",1,"Which neighbors got generators, which ones got pills - which one's got a gun safe and a bad hip",2,"Sweet lady",1,"Gun safe fella ran over her cat in eighty-nine, she had the year right on the tip of her tongue"}},
{"s7_c01_carry_stuff_027","any",3,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"Kid we stopped at the bridge asked could he come with us",2,"You let him come along?",1,"Said no, he said please, he'd carry stuff, said he was strong for his age",3,"How old?",1,"Old enough to carry stuff, too young to watch what we do after",2,"Good call",1,"Wasn't a call, I just didn't want him looking at me every morning"}},
{"s7_c01_ice_cream_truck_028","any",3,"reg=raider|mood=funny|world=vehicle,water,road,rain",{1,"Stopped an ice cream truck on the Rosewood road, music box still playing",2,"What was he hauling?",1,"Everything melted into one puddle, smells like a birthday party in a swamp back there",3,"So we got nothing",1,"We got the truck, and the music, nobody knows how to shut off the music",2,"Rip the speaker out before it calls every dead thing in {town} to line up"}},
{"s7_c01_long_sigh_029","any",2,"reg=raider|tmp=predator|day=5,200|hour=4,11|mood=funny",{1,"Fella at the church lot saw us coming and just sighed - long, long sigh",2,"Sighed?",1,"Said boys, I been hit twice already this morning, the Brandenburg bunch took my boots",2,"So what'd we get?",1,"His sympathy, said at least we were polite about it"}},
{"s7_c01_marine_porch_030","any",3,"reg=raider|mood=fear|world=window",{1,"The old Marine with the flag on his porch told us exactly how he'd do it",2,"Do what?",1,"Kill us - step by step, who first, which window, which ditch he'd use after",3,"And we still took the cooler",1,"We took the cooler, he had a cane - didn't make it feel one bit better"}},
{"s7_c01_watch_for_a_bullet_031","any",2,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Man on the overpass asked us to shoot him, offered his watch for it",2,"Did you?",1,"Took the watch",2,"That ain't what I asked",1,"I know what you asked"}},
{"s7_c01_marina_drunk_032","any",3,"reg=raider|day=3,20|mood=funny|world=water",{1,"Drunk asleep in a johnboat behind the marina, didn't know a thing",2,"Nothing at all?",1,"Asked us was the party over, said he'd been out on the water since Thursday",3,"You tell him?",1,"Told him the party got out of hand, took his cooler - he said, well, that tracks"}},
{"s7_c01_plastic_leg_033","any",2,"reg=raider|tmp=predator,seasoned|mood=warm",{1,"What'd the one-legged fella have on him?",2,"A leg - nice one, plastic and steel",1,"You didn't",2,"Course I didn't - who am I gonna sell a leg to? He had a can of sardines - I let him keep that, too"}},
{"s7_c01_beekeeper_034","any",3,"reg=raider|mood=funny",{1,"Beekeeper out past March Ridge, full white suit, the veil, everything",2,"Get anything?",1,"Six jars of honey, and a sting on my eyelid for each jar",2,"He sicced the bees on you?",1,"Kicked a hive box over on his way to putting his hands up - swore it was an accident",3,"Wasn't no accident"}},
{"s7_c01_tobacco_barn_035","any",3,"reg=raider|tmp=predator|day=5,200|mood=grim|world=door,window,road",{1,"I remember a family choosing a tobacco barn over a house",2,"Why the barn?",1,"They figured fewer windows meant less to worry about",3,"One door could trap them too",1,"Yeah. You can't know a place is safe, or that people have no water, just by calling it a barn"}},
{"s7_c01_pacifier_cupholder_036","any",3,"reg=raider|tmp=predator,seasoned|mood=sad|world=window",{1,"There's a pacifier in the cupholder of this Blazer",2,"That's off the family at the rest stop",1,"I know who it's off of",2,"So chuck it out the window",1,"It ain't hurting nobody in the cupholder",3,"Leave him alone - drive"}},
{"s7_c01_one_open_window_037","any",3,"reg=raider|tmp=predator|day=5,200|mood=calm|world=window,building,road",{1,"Plywood on every window of that two-story but one - upstairs bathroom",2,"Left it for the air",1,"Or for a rifle, either way, that's the room he sleeps closest to",3,"So we come in the side, under it",1,"Or we holler from the road and let him burn his shells on the mailbox"}},
{"s7_c01_mutter_phone_books_038","any",1,"reg=raider|tmp=predator,seasoned|mood=calm",{1,"Four-eleven - four-fifteen, four-nineteen's got the cat",1,"Can't quit reading house numbers, delivered phone books three summers, that's why",1,"Back then I knew who tipped, now I know who answers"}},
{"s7_c01_booster_bats_039","any",2,"reg=raider|mood=funny",{1,"Coach at the ball field had a bag of aluminum bats - nine of 'em",2,"Good for heads",1,"He said they belonged to the team, said the boosters paid for 'em",2,"Tell the boosters to come see us",1,"He wrote our plate number on his lineup card, said he'd be filing a complaint"}},
{"s7_c01_pruitt_setup_040","any",3,"reg=raider|tmp=predator|hour=4,11|mood=angry",{1,"Why'd that woman send us to the Pruitt place? Said it was full of food",2,"The Pruitt place was full of Pruitts - with shotguns",1,"She set us up",3,"She set us up and she's still sitting on her porch swing - waved at me this morning",2,"The wave's what makes it personal"}},
{"s7_c01_two_wagons_041","any",3,"reg=raider|tmp=predator|mood=grim|world=building",{1,"Two sisters, two station wagons, both loaded to the roof",2,"Take both",1,"We only got one spare driver",3,"Then take the one with the full tank",1,"Full tank's got the grandma in the back seat",3,"Grandma can ride with the other sister - get her out gentle"}},
{"s7_c01_short_straw_042","any",3,"reg=raider,prison|tmp=predator|mood=angry",{1,"Straws for the Bowie knife, short one wins",2,"Short one? Since when does short win?",1,"Since I'm the one holding the straws",3,"Let me see your other hand",1,"Ain't nothing in my other hand",3,"Then open it"}},
{"s7_c01_kennys_share_043","any",3,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"Kenny's share from Tuesday, it's still sitting in the bag",2,"Kenny ain't gonna need it",3,"His girl might, she's at the trailer by the quarry with his baby",2,"Kenny's girl never did nothing for this crew",3,"She washed your shirts for a month",2,"Then she gets the shirt money, split the rest"}},
{"s7_c01_silver_half_044","any",2,"reg=raider,prison|mood=funny",{1,"Flip for the sunglasses, heads, they're mine",2,"Where'd you get a half dollar?",1,"Old man's coin book - nineteen sixty-four - real silver",2,"Then I want the coin - forget the sunglasses",1,"Too late, it's in the air"}},
{"s7_c01_squares_per_man_045","any",3,"reg=raider,prison|mood=funny",{1,"Nobody touches the toilet paper, that's crew property",2,"I found it, I carried eight rolls a mile in a pillowcase",1,"Thanks for the service, it's still crew property",3,"Put a count on it, eighteen squares a day, a man",2,"Eighteen? What am I, a parakeet?"}},
{"s7_c01_westerns_bag_046","any",3,"reg=raider|hour=16,5|mood=warm",{1,"Doyle, what's in your share bag? It's heavy as a toolbox",2,"Paperbacks, westerns, off that old man's shelf",1,"We're taking ammo and you're taking cowboys",2,"Ammo runs out, a cowboy I can read twice",3,"Read one out loud tonight, then, you're the only one of us reads good"}},
{"s7_c01_tanya_drove_047","any",3,"reg=raider|tmp=predator|mood=angry|world=vehicle",{1,"Why's Tanya pulling a full share? She never went in",2,"She drove",1,"She sat in the truck with the radio on",3,"That radio's the scanner, she heard the deputies coming before any of you did",1,"What deputies? There ain't hardly any deputies left",3,"There was three on Tuesday, you'd have met 'em if she hadn't been listening"}},
{"s7_c01_laundromat_silent_048","any",3,"reg=raider|tmp=predator,seasoned|mood=fear",{1,"Woman at the laundromat never said one word, not please, not a thing",2,"Maybe she was deaf",1,"She heard fine, she moved when I said move",3,"Some of 'em are just done talking",1,"Made my skin crawl worse than any screamer"}},
{"s7_c01_slips_out_of_third_049","any",3,"reg=raider|mood=funny",{1,"Man we took the Jeep off of laughed the whole time - hahaha, like we were old buddies",2,"Laughing at what?",1,"Said the transmission was shot and he'd been trying to sell it since May",3,"Is it shot?",1,"Slips out of third on every hill, he laughed at that part too, said good luck, boys"}},
{"s7_c01_prayer_on_the_hood_050","any",3,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Man asked could he pray before we searched him, knelt right down on the gravel",2,"And you let him",1,"Took about a minute, he prayed for his wife, his dog, and then for Curtis - by name",3,"How'd he know my name?",2,"'Cause you yelled it at me twice, dumbass",3,"Still, I didn't ask him to do that"}},
{"s7_c01_gravel_drive_rule_051","any",2,"reg=raider|tmp=predator|day=4,200|mood=calm|world=building",{1,"Gravel driveway, you walk the grass, always the grass",2,"Everybody knows that",1,"Jimmy don't - Jimmy crunched up that drive Friday like a marching band",2,"And that's how that family was already out the back and gone"}},
{"s7_c01_flies_front_door_052","any",2,"reg=raider|tmp=predator|day=8,200|mood=grim|world=door",{1,"House behind the Dairy Queen had a family - past tense",2,"We ain't been there yet",1,"Somebody has, front door's standing open and flies are going in and out",2,"Cross it off, then",1,"Crossed off, somebody beat us to it, and they didn't take the canned stuff - just the people"}},
{"s7_c02_boss_whistling_001","any",3,"reg=raider|tmp=predator,seasoned|mood=fear",{1,"He's whistling",2,"Whistling's bad?",3,"Whistling's the worst, yelling means he's done being mad, whistling means he ain't started",2,"What's he whistling?",1,"Don't matter what, just don't be the next thing he looks at"}},
{"s7_c02_truck_door_hand_002","any",3,"reg=raider|tmp=predator,seasoned|mood=grim|world=vehicle,door",{1,"Dale shut Terry's hand in the truck door - twice",2,"Over two cans of chili?",1,"Over lying about two cans of chili, he'd have let the cans go",3,"Terry can't hold a rifle now, can't even button his jeans",1,"That was kind of the point"}},
{"s7_c02_beans_in_fire_003","any",3,"reg=raider|tmp=predator|hour=17,23|mood=funny",{1,"Who said the beans were burnt?",2,"Cody",1,"And now there ain't no beans - thanks, Cody",3,"He dumped the whole pot in the fire, grabbed it by the handle, no rag, nothing",2,"Palm's all blistered and he still ain't said ouch",1,"He won't, not while Cody's alive to hear it"}},
{"s7_c02_molar_004","any",3,"reg=raider|tmp=predator|mood=funny",{1,"Boss's back tooth is killing him, whole side of his face is swole up like a softball",2,"So that's why he pistol-whipped the gas station kid",3,"Somebody find a dentist, a live one",1,"Or a pair of pliers, a bottle, and somebody brave",2,"I'll find the pliers, I ain't the brave"}},
{"s7_c02_called_me_son_005","any",3,"reg=raider|tmp=predator|day=7,200|mood=fear|world=fence",{1,"He called me son today",2,"Oh, no",1,"Said, son, go check the back fence for me - real soft",3,"Last one he called son was Dewey - Dewey went to check the back fence last Wednesday",1,"Where's Dewey at now?",3,"Go check the fence, take a flashlight"}},
{"s7_c02_shot_the_radio_006","any",3,"reg=raider|tmp=predator|day=4,60|mood=angry",{1,"Why's there a bullet hole in the radio?",2,"Army tape again, same one - 'stay in your homes, help is on the way'",1,"So he shot it",2,"Said he's tired of being lied to in his own camp",3,"That was our only radio",2,"Go tell him that, go on - I'll wait right here"}},
{"s7_c02_plate_on_step_007","any",3,"reg=raider|tmp=predator,seasoned|day=5,200|mood=sad|world=door",{1,"I remember the boss shutting himself in after we buried his brother",2,"Wouldn't come out for two days",3,"Did somebody take him a plate?",1,"Last one who knocked got a boot through the screen door",3,"I'd have left it on the step. Let him choose whether to come out"}},
{"s7_c02_family_speech_008","any",3,"reg=raider|tmp=predator|mood=funny|world=building,rooftop,rain",{1,"We're a family now, he says - a family",2,"My family never made me sleep on a roof in the rain",3,"Your family never fed you neither, way you tell it",2,"That's fair",1,"So he's the dad that feeds you and puts you on the roof - congratulations, you got adopted"}},
{"s7_c02_ask_rhonda_first_009","any",2,"reg=raider|tmp=predator|mood=calm",{1,"You want something off Dale, you ask Rhonda first",2,"Rhonda don't even carry a gun",1,"She don't need one, she tells Dale who's been running his mouth - Dale's got plenty of guns",2,"So what's Rhonda like?",1,"Menthols and compliments - mostly menthols"}},
{"s7_c02_church_shoes_dance_010","any",2,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Made that heavy fella dance for his truck keys - hahaha! You see him go?",2,"I saw",1,"Little shuffle in them church shoes, should've had music",2,"He had a heart thing, nitro pills in his shirt pocket - I saw the bottle",1,"Well, he danced fine",2,"Yeah, he did"}},
{"s7_c02_trunk_since_supper_011","any",3,"reg=raider|tmp=predator,seasoned|hour=21,4|mood=fear|world=vehicle",{1,"Remember the fella they left in a trunk?",2,"What fella?",1,"The Oldsmobile. Nobody checked on him till after supper",3,"Oh, hell",2,"Somebody said he'd be fine because it was cooler at night",1,"That wasn't knowing he was fine. That's the part that still bothers me"}},
{"s7_c02_tied_to_fence_012","any",3,"reg=raider|tmp=predator,seasoned|mood=angry|world=fence,road",{1,"You don't tie a man to a fence, you take his stuff and you let him run",2,"Boss said make an example",1,"An example for who? Ain't nobody on that road but them",2,"Then it's an example for them",1,"I'm going back and cutting him loose",3,"Go on, then, go on and explain it to Dale when you get back"}},
{"s7_c02_eyeglasses_dash_013","any",3,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"What's with all the eyeglasses lined up on the dash?",2,"One pair for every one that cried, I'm up to eleven",3,"That's sick, man",2,"That's a hobby, your problem is you ain't got one",3,"Throw 'em out or I'm riding in the bed",2,"Bed's open - mind the chainsaw"}},
{"s7_c02_burned_house_tomatoes_014","any",3,"reg=raider|tmp=predator,seasoned|mood=grim|world=fire",{1,"Why'd you burn it? We already had everything out",2,"So they don't crawl back and live in it",3,"They can see that smoke from Fort Knox - you know what else sees smoke? Helicopters",2,"Let 'em look",1,"They had a garden out back, tomatoes were two days off from ripe"}},
{"s7_c02_can_on_porch_015","any",2,"reg=raider|tmp=predator,seasoned|mood=warm|world=door,building",{1,"You set a can back on that porch, I watched you do it",2,"It fell out of the sack",1,"Fell out, walked up three steps, and set itself down by the door",2,"You gonna tell him?",1,"Next time set two, there was a kid in there"}},
{"s7_c02_new_boy_puked_016","any",3,"reg=raider|tmp=predator|mood=grim",{1,"New boy threw up out behind the gas station",2,"Everybody does, first time",3,"I didn't",2,"I know you didn't, that's why nobody sits by you"}},
{"s7_c02_loyal_dog_017","any",2,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"You didn't have to shoot the dog",2,"Dog was barking, barking brings 'em",1,"The dog was barking 'cause you were beating on his man",2,"So it's my fault the dog was loyal?",1,"Yeah, actually - it is"}},
{"s7_c02_used_to_steal_cars_018","any",2,"reg=raider|tmp=predator,seasoned|day=6,200|mood=sad|world=vehicle,cars",{1,"Before, I stole cars - just cars, nobody ever cried at me over a car",2,"Everybody cries over a car now, a car's a house",1,"Yesterday we took a car with a man's whole life in the trunk - didn't feel a thing",2,"Good, that's the job now",1,"I didn't say it was good"}},
{"s7_c02_shirt_off_road_019","any",2,"reg=raider|tmp=predator,seasoned|mood=angry|world=road",{1,"Why'd you make the old man take his shirt off in the middle of the road?",2,"Checking for bites",1,"We weren't letting him in, we were robbing him - who cares is he bit?",2,"I care, I like to know",1,"You like to watch 'em shake is what you like"}},
{"s7_c02_boots_to_bed_020","any",3,"reg=raider,prison|tmp=predator|mood=fear",{1,"You sleep with your boots on now?",2,"Since Floyd's went missing, right off his feet, while he was asleep",3,"Floyd says it was a raccoon",2,"A raccoon that wears a ten and a half"}},
{"s7_c02_mitch_gas_question_021","any",2,"reg=raider|tmp=predator|hour=16,5|mood=fear|world=vehicle",{1,"Mitch asked me yesterday how much gas is in the red truck",2,"So?",1,"So Mitch ain't got nowhere to drive, unless he's driving away",2,"Or driving to Brandenburg to tell that crew where we park the red truck",1,"I'm sleeping in the red truck tonight"}},
{"s7_c02_skeeter_cooking_022","any",3,"reg=raider,prison|tmp=predator|mood=funny",{1,"I don't eat nothing Skeeter cooks no more",2,"Why not?",1,"I owe him forty shells, and he's being real nice about it",3,"He put hot sauce in yours, that's him being nice",1,"That's what he wants you to think the hot sauce is for"}},
{"s7_c02_hypothetically_023","any",3,"reg=raider|tmp=predator|mood=fear",{1,"If something ever happened to Dale - Hypothetical",2,"Don't",1,"I'm just asking who'd run things - hypothetically",3,"Hypothetically, Rhonda'd shoot whoever said hypothetically first",1,"Forget I said nothing",2,"Already did, didn't hear a word, wasn't even here"}},
{"s7_c02_mutter_stopped_talking_024","any",1,"reg=raider,prison|tmp=predator|hour=18,2|mood=fear|world=vehicle,stairs,building,rooftop",{1,"Three of 'em by the truck, talking low, quit the second I walked up",1,"Could be about cards, could be about me",1,"Sleeping on the roof tonight, pulling the ladder up after me"}},
{"s7_c02_mutter_ceiling_tiles_025","any",1,"reg=raider|tmp=seasoned,predator|mood=sad|world=vehicle,door,building",{1,"Signed up for a truck and a share, didn't sign up for kids crying",1,"Stood in that doorway looking at the ceiling the whole time - counted the tiles - forty",1,"Forty ceiling tiles, guess I'll know that number the rest of my life"}},
{"s7_c02_hood_won_026","any",3,"reg=raider|tmp=predator|mood=funny|world=vehicle",{1,"Boss punched the hood of the truck",2,"Who won?",1,"Hood won - two knuckles - don't laugh where he can hear",3,"I ain't laughing - I'm coughing",2,"Cough quieter"}},
{"s7_c02_school_buses_noon_027","any",3,"reg=raider|tmp=predator|day=5,60|mood=grim|world=cars,door",{1,"Told that family the evac buses leave from the Muldraugh school at noon",2,"There ain't no buses",1,"No, but their house'll be real empty at noon, won't it",3,"We saw movement at those gym doors Tuesday. You sent them without even checking what was there now",1,"Forgot about that part",3,"No you didn't"}},
{"s7_c02_river_road_tip_028","any",2,"reg=raider|tmp=seasoned,predator|mood=calm|world=water,road",{1,"What'd you whisper to that man before he walked?",2,"Told him take the river road",1,"Why the river road?",2,"'Cause we ain't working the river road this week",1,"You're gonna get us all hung, doing favors"}},
{"s7_c02_pockets_out_029","any",3,"reg=raider|role=raider_boss,raider|tmp=predator|mood=angry",{1,"Line up - pockets out, every one of you",2,"Dale, it's us, we been with you since the start",1,"The start was ten days ago - pockets",3,"He's got a candy bar down his sock",2,"It's half a candy bar, I'll split it - Jesus, I'll split it with everybody"}},
{"s7_c02_dinner_bell_shot_030","any",2,"reg=raider|tmp=predator|mood=angry|world=water",{1,"Who fired that shot by the creek?",2,"Snake, at a copperhead",1,"Every shot's a dinner bell, and he rang it for a snake",2,"He's digging the latrine all week, boss already told him",1,"Good, tell him dig it by the creek, next to his copperhead"}},
{"s7_c02_dinosaur_inhaler_031","any",2,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"Why'd you take the kid's inhaler?",2,"It's medicine - medicine trades",1,"Who's trading for a half-used inhaler with a dinosaur sticker on it?",2,"Somebody with asthma",1,"Somebody like the kid"}},
{"s7_c02_think_about_them_032","any",3,"reg=raider|tmp=predator,seasoned|hour=21,3|mood=sad|world=inside",{1,"You ever think about the ones we leave walking?",2,"No",1,"Not even the old lady with the oxygen tank?",2,"I said no",3,"Put another log on, somebody, it's getting dark in here"}},
{"s7_c02_arlo_leaving_033","any",2,"reg=raider|tmp=seasoned,predator|hour=22,4|mood=fear",{1,"I'm leaving - tonight - you coming?",2,"Shh- quieter!",1,"Rhonda's asleep - Dale's drunk, keys are on the nail",2,"And go where? Every crew in the county knows your face - the Army shoots anybody carrying",1,"So you're staying",2,"I didn't hear none of this - go to bed, Arlo"}},
{"s7_c02_just_to_see_034","any",3,"reg=raider|tmp=predator,seasoned|mood=angry",{1,"We could push him out toward the pack at the lumber yard - just to see how fast they are",2,"We know how fast they are",1,"Not with a fat one - science",3,"Say one more word about it and I'll push you out there - science",1,"Everybody's so touchy lately"}},
{"s7_c02_watch_rotation_035","any",3,"reg=raider|tmp=predator|hour=19,23|mood=angry",{1,"Watch tonight is Curtis and Vernon",2,"I ain't standing watch with Vernon",3,"And I ain't standing it with Curtis, he knows why",1,"Then you both stand it facing each other and the dead can walk right in between - great plan",2,"Fine, but he walks in front"}},
{"s7_c02_the_list_in_his_head_036","any",2,"reg=raider|tmp=predator|day=10,200|mood=fear",{1,"Dale keeps a list, in his head, every time somebody sasses him",2,"How long's the list?",1,"Nobody knows, that's how a list in a head works",2,"I asked him for more coffee Monday - is that on it?",1,"Depends how you asked"}},
{"s7_c02_hand_in_the_fire_037","any",2,"reg=raider|tmp=predator|mood=grim|world=building",{1,"The man we took the shotgun off - Dale made him hold his hand over the fire",2,"For how long?",1,"Till he told us where the shells were, then a little longer, 'cause he'd made us wait",2,"Where were they?",1,"In the mailbox, hell of a place for shells, I'd never have looked"}},
{"s7_c02_hot_boss_hot_crew_038","any",3,"reg=raider|tmp=predator|hour=12,17|mood=funny|world=building,water",{1,"Above ninety, stay away from the boss",2,"What about above ninety-five?",1,"Above ninety-five, stay away from the county",3,"Thermometer on the porch says a hundred and one",1,"Then I'm in the creek - tell him I drowned"}},
{"s7_c02_wrong_one_shot_039","any",3,"reg=raider|tmp=predator,seasoned|mood=grim",{1,"Vernon shot the one who was doing what we said - the other one was the one reaching",2,"It was dark, they both moved",1,"One of 'em moved toward his pocket, the other one moved to get his hands higher",3,"We gonna tell Dale?",2,"Tell him what? We got the stuff"}},
{"s7_c02_toothbrush_skim_040","any",2,"reg=raider,prison|tmp=predator|mood=fear",{1,"Somebody's been in my bag, my toothbrush is on the wrong side",2,"Your toothbrush",1,"I keep it on the left, it's on the right - somebody took everything out and put it back wrong",2,"Anything missing?",1,"No, that's what scares me, they were looking for something I ain't got yet"}},
{"s7_c02_boss_mama_record_041","any",3,"reg=raider|tmp=predator,seasoned|day=8,200|hour=20,3|mood=sad|world=building",{1,"Boss has the cassette player going in his camper, same tape, over and over",2,"What's on it?",1,"His mama, church program from Easter, she's reading the announcements",3,"Covered dish supper Wednesday, bring a folding chair",1,"You been listening at his window?",3,"Everybody has, the walls are tin"}},
{"s7_c02_break_fingers_math_042","any",3,"reg=raider|tmp=predator|mood=funny",{1,"Rule is one finger per can you skim",2,"What if you skim eleven cans?",3,"Then he starts on your toes",2,"And after the toes?",1,"Nobody's ever got past toes, Junior - put the peaches back"}},
{"s7_c02_crying_cheaper_043","any",2,"reg=raider|tmp=predator|mood=grim",{1,"Criers are easier, they hand it over quick so you'll leave",2,"And the quiet ones?",1,"Quiet ones are counting you, hit a quiet one twice as hard and twice as fast",2,"And the ones that pray?",1,"Ones that pray, send Shane in - Shane don't mind being prayed at"}},
{"s7_c02_shane_minds_044","any",3,"reg=raider|tmp=predator,seasoned|mood=sad|world=water,hot",{1,"Shane, they keep sending you in on the praying ones",2,"'Cause I don't mind",3,"You mind, you go sit in the creek after every time",2,"It's hot - creek's cold",3,"You sit in it with your clothes on, Shane"}},
{"s7_c02_rhonda_softened_045","any",3,"reg=raider|tmp=predator|mood=warm",{1,"Rhonda talked Dale out of it, the kid with the slingshot",2,"How?",1,"Said something in his ear - Dale put the belt back on and walked off",3,"What'd she say?",1,"Asked her, she said she reminded him what his daddy used that belt for"}},
{"s7_c02_lying_down_on_watch_046","any",3,"reg=raider|tmp=predator|hour=5,9|mood=angry|world=fence",{1,"Dewitt was asleep on watch - Dale found him with his mouth open and his rifle in the grass",2,"What'd he do?",1,"Took the rifle, took his boots, told him he could have 'em back after he walks the fence line barefoot",3,"The fence line's all blackberry briars",1,"That's why you don't sleep"}},
{"s7_c02_good_ones_bad_ones_047","any",2,"reg=raider|tmp=seasoned,predator|day=14,200|mood=grim",{1,"There's a line, I don't know where it is - but I'd like to think I'd notice when I stepped over it",2,"You stepped over it the first Tuesday",1,"The Tuesday? That was just groceries",2,"That was a lady's groceries with the lady standing there - that's the line"}},
{"s7_c02_names_in_notebook_048","any",3,"reg=raider|tmp=predator|mood=fear",{1,"Found a notebook in Travis's bag, got all our names in it - dates, too",2,"Names and dates of what?",1,"What we did, who we did it to - addresses",3,"He's keeping evidence, for when the law comes back",2,"Law ain't coming back",3,"He thinks it is - that's worse"}},
}
